import React from 'react';
import './MarkdownView.css';

/**
 * Lightweight, safe parser for Markdown generated by Gemini.
 * Supports bold, headers, bullet lists, numbered lists, code, and markdown tables.
 */
const parseInline = (text) => {
    // Replace bold **text** with <strong>text</strong>
    const parts = [];
    const boldRegex = /\*\*(.*?)\*\*/g;
    let lastIndex = 0;
    let match;

    while ((match = boldRegex.exec(text)) !== null) {
        if (match.index > lastIndex) {
            parts.push(text.substring(lastIndex, match.index));
        }
        parts.push(<strong key={`bold-${match.index}`}>{match[1]}</strong>);
        lastIndex = match.index + match[0].length;
    }

    if (lastIndex < text.length) {
        parts.push(text.substring(lastIndex));
    }

    return parts.length > 0 ? parts : text;
};

const MarkdownView = ({ content }) => {
    if (!content) return null;

    const lines = content.split('\n');
    const elements = [];
    let listItems = [];
    let listType = null; // 'ul' or 'ol'
    let tableRows = [];
    let inTable = false;

    const flushList = () => {
        if (listItems.length > 0) {
            if (listType === 'ol') {
                elements.push(
                    <ol key={`ol-${elements.length}`}>
                        {listItems.map((item, idx) => (
                            <li key={idx}>{parseInline(item)}</li>
                        ))}
                    </ol>
                );
            } else {
                elements.push(
                    <ul key={`ul-${elements.length}`}>
                        {listItems.map((item, idx) => (
                            <li key={idx}>{parseInline(item)}</li>
                        ))}
                    </ul>
                );
            }
            listItems = [];
            listType = null;
        }
    };

    const flushTable = () => {
        if (tableRows.length > 0) {
            const headerRow = tableRows[0];
            const bodyRows = tableRows.slice(1);
            elements.push(
                <table key={`table-${elements.length}`}>
                    <thead>
                        <tr>
                            {headerRow.map((cell, idx) => (
                                <th key={idx}>{parseInline(cell)}</th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {bodyRows.map((row, rIdx) => (
                            <tr key={rIdx}>
                                {row.map((cell, cIdx) => (
                                    <td key={cIdx}>{parseInline(cell)}</td>
                                ))}
                            </tr>
                        ))}
                    </tbody>
                </table>
            );
            tableRows = [];
            inTable = false;
        }
    };

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();

        // Table detection
        if (line.startsWith('|') && line.endsWith('|')) {
            flushList();
            inTable = true;
            // Ignore separator line like |---|---|
            if (line.includes('---')) {
                continue;
            }
            const cells = line
                .split('|')
                .slice(1, -1)
                .map(c => c.trim());
            tableRows.push(cells);
            continue;
        } else if (inTable) {
            flushTable();
        }

        // Header detection
        if (line.startsWith('### ')) {
            flushList();
            elements.push(<h3 key={`h3-${i}`}>{parseInline(line.replace('### ', ''))}</h3>);
            continue;
        }
        if (line.startsWith('#### ')) {
            flushList();
            elements.push(<h4 key={`h4-${i}`}>{parseInline(line.replace('#### ', ''))}</h4>);
            continue;
        }

        // Unordered list detection
        if (line.startsWith('* ') || line.startsWith('- ')) {
            if (listType === 'ol') flushList();
            listType = 'ul';
            listItems.push(line.replace(/^[*\-]\s+/, ''));
            continue;
        }

        // Ordered list detection (1. , 2. )
        const numMatch = line.match(/^\d+\.\s+(.*)/);
        if (numMatch) {
            if (listType === 'ul') flushList();
            listType = 'ol';
            listItems.push(numMatch[1]);
            continue;
        }

        // Regular line or empty line
        flushList();

        if (line.length > 0) {
            elements.push(<p key={`p-${i}`}>{parseInline(line)}</p>);
        }
    }

    flushList();
    flushTable();

    return <div className="markdown-view">{elements}</div>;
};

export default MarkdownView;
